        'К ним относятся: тот, кто совершает действие (الْفَاعِلُ), тот, над кем совершили действие (الْمَفْعُولُ الَّذِي لَمْ يُسَمَّ فَاعِلُهُ), главное слово в начале предложения (المُبْتَدَأُ) и новость о нём (خَبَرُهُ).',
