        'Я слышал, как посланник Аллаха, да благословит его Аллах и приветствует, говорил:',
        '“Аллах Всевышний сказал: ‘О сын Адама, поистине, до тех пор, пока ты не перестанешь взывать ко Мне и надеяться на Меня, Я буду прощать тебе, не обращая внимания на то, какие (грехи) ты (совершил)! О сын Адама, если совершишь ты столько грехов, что достигнув они туч небесных, а потом попросишь у Меня прошения, то Я прошу тебя! О сын Адама, поистине, если придешь ты ко Мне с (таким количеством) прегрешений (, что заполнят они собой) чуть ли не всю землю, но встретишь Меня, не поклоняясь наряду со Мной ничему иному, Я обязательно дарую тебе прощение, которое (покроет собой все эти грехи)’”.»',
