      { q:'Слово «أَبًا» во фразе «خَالِدٌ أَكْرَمُ مِنْكَ أَبًا» — это:', opts:['حال','اسم من الأسماء الخمسة في محل جر','تمييز منصوب بالفتحة'], a:2 },
      { q:'Является ли «التَّمْيِيزُ» одним из «الْمَنْصُوبَاتُ»?', opts:['Да','Нет','Только в افعال'], a:0 },
      { q:'Приведи по одному собственному примеру «التَّمْيِيزُ» после глагола, после числительного и после сравнения.', open:true }
