      { q:'Если мы говорим «خَلَا خَالِدٍ» (с касрой), то «خَلَا» — это:', opts:['فعل ماض','حرف جر (и Халид — اسم مجرور)','مبتدأ'], a:1 },
      { q:'Опиши все 3 случая («تَامٌّ مُوجَبٌ», «مَنْفِيٌّ تَامٌّ», «نَاقِصٌ») для И\'раба слова после «إِلَّا», приведя пример на каждый.', open:true }
